import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import '../../../core/errors/app_error.dart';
import '../../auth/presentation/auth_scope.dart';
import '../data/reporter_economy_repository.dart';
import '../domain/reporter_economy.dart';

class ReporterWorkspaceScreen extends StatefulWidget { const ReporterWorkspaceScreen({required this.mode, super.key}); final String mode; @override State<ReporterWorkspaceScreen> createState()=>_State(); }
class _State extends State<ReporterWorkspaceScreen> {
  ReporterEconomyRepository? repo; ReporterEconomyData? data; bool loading=true,sending=false; String? error; int days=30;
  final amount=TextEditingController(),bank=TextEditingController(),holder=TextEditingController(),account=TextEditingController(),code=TextEditingController(),phone=TextEditingController();
  @override void didChangeDependencies(){super.didChangeDependencies();if(repo!=null)return;final c=AuthScope.read(context).service.client;if(c==null){loading=false;error='Supabase is not configured.';}else{repo=ReporterEconomyRepository(c);load();}}
  @override void dispose(){for(final c in [amount,bank,holder,account,code,phone]){c.dispose();}super.dispose();}
  Future<void> load()async{setState((){loading=true;error=null;});try{final x=await repo!.load(widget.mode,days);if(mounted)setState(()=>data=x);}catch(e){if(mounted)setState(()=>error=AppError.message(e));}finally{if(mounted)setState(()=>loading=false);}}
  Future<void> withdraw()async{final w=data?.wallet,value=num.tryParse(amount.text),digits=phone.text.replaceAll(RegExp(r'\D'),'');if(value==null||w==null||value<w.minimum||value>w.available){setState(()=>error='Enter an amount between ${w?.minimum??100} and ${w?.available??0}.');return;}if([bank,holder,account,phone].any((x)=>x.text.trim().isEmpty)||digits.length<7||digits.length>15){setState(()=>error='Complete valid bank and phone details.');return;}setState(()=>sending=true);try{await repo!.requestWithdrawal(amount:value,bankName:bank.text.trim(),accountHolder:holder.text.trim(),accountNumber:account.text.trim(),bankCode:code.text.trim(),phoneNumber:phone.text.trim());for(final c in [amount,bank,holder,account,code,phone]){c.clear();}await load();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Withdrawal request submitted.')));}catch(e){if(mounted)setState(()=>error=AppError.message(e));}finally{if(mounted)setState(()=>sending=false);}}
  @override Widget build(BuildContext context)=>SafeArea(child:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(16,20,16,80),children:[Wrap(spacing:8,children:[for(final x in const [('dashboard','Dashboard'),('points','Points'),('wallet','Wallet')])ChoiceChip(label:Text(x.$2),selected:widget.mode==x.$1,onSelected:(_)=>context.go('/${x.$1}')),ActionChip(label:const Text('Leaderboard'),onPressed:()=>context.go('/reporters')),ActionChip(label:const Text('My stories'),onPressed:()=>context.go('/my-stories'))]),const SizedBox(height:18),Text(widget.mode=='dashboard'?'Reporter dashboard':widget.mode=='points'?'Points ledger':'Wallet & withdrawals',style:Theme.of(context).textTheme.headlineMedium),if(error!=null)Card(color:Theme.of(context).colorScheme.errorContainer,child:Padding(padding:const EdgeInsets.all(12),child:Text(error!))),if(loading)const Padding(padding:EdgeInsets.all(40),child:Center(child:CircularProgressIndicator()))else ...content(context)])));
  List<Widget> content(BuildContext context){final d=data;if(d==null)return[const Text('No data available.')];final s=d.stats;if(widget.mode=='dashboard'){final p=d.performance;return[DropdownButton<int>(value:days,items:const[DropdownMenuItem(value:7,child:Text('Last 7 days')),DropdownMenuItem(value:30,child:Text('Last 30 days')),DropdownMenuItem(value:36500,child:Text('All time'))],onChanged:(v){if(v!=null){days=v;load();}}),metrics([('Points',s?.points??0),('Published',s?.published??0),('Followers',s?.followers??0),('Rating',s?.rating??0),('Trust',s?.trust??0),('Views',p?.views??0),('Unique views',p?.uniqueViews??0),('Likes',p?.likes??0),('Comments',p?.comments??0),('Pending',p?.pending??0),('Changes requested',p?.changes??0),('Rejected',p?.rejected??0)]),if(p?.daily.isNotEmpty==true)...[Text('Daily views',style:Theme.of(context).textTheme.titleLarge),...p!.daily.map((x)=>ListTile(dense:true,title:Text(x.day),trailing:Text('${x.views}')))]];}if(widget.mode=='points')return[metrics([('Total points',s?.points??0)]),...entries(d.points,'No points activity yet.')];final w=d.wallet;return[metrics([('Available',w?.available??0),('Pending',w?.pending??0),('Reserved',w?.reserved??0),('Withdrawn',w?.withdrawn??0),('Minimum',w?.minimum??100)]),const SizedBox(height:18),Text('Request bank withdrawal',style:Theme.of(context).textTheme.titleLarge),...[(amount,'Amount'),(bank,'Bank name'),(holder,'Account holder'),(account,'Account number / IBAN'),(code,'Bank / branch code (optional)'),(phone,'Phone number')].map((x)=>Padding(padding:const EdgeInsets.only(top:10),child:TextField(controller:x.$1,keyboardType:x.$1==amount?TextInputType.number:null,decoration:InputDecoration(labelText:x.$2,border:const OutlineInputBorder())))),const SizedBox(height:12),FilledButton.icon(onPressed:sending?null:withdraw,icon:const Icon(Icons.account_balance_rounded),label:Text(sending?'Submitting…':'Request withdrawal')),const SizedBox(height:20),Text('Transactions',style:Theme.of(context).textTheme.titleLarge),...entries(d.transactions,'No wallet transactions yet.'),Text('Withdrawal history',style:Theme.of(context).textTheme.titleLarge),...entries(d.withdrawals,'No withdrawals yet.')];}
  Widget metrics(List<(String,num)> xs)=>Wrap(spacing:10,runSpacing:10,children:xs.map((x)=>SizedBox(width:155,child:Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(x.$1),Text('${x.$2}',style:Theme.of(context).textTheme.titleLarge)]))))).toList());
  List<Widget> entries(List<EconomyEntry> xs,String empty)=>xs.isEmpty?[Padding(padding:const EdgeInsets.all(16),child:Text(empty))]:xs.map((x)=>Card(child:ListTile(title:Text(x.label),subtitle:Text([x.status,x.createdAt].where((v)=>v.isNotEmpty).join(' • ')),trailing:Text('${x.amount} ${x.currency}')))).toList();
}
